import React from 'react';
import {MontantAvecTaxes} from '../util/MontantAvecTaxes.js';

class TaxeQC extends React.Component {

    state = {
        montantAvecTaxe: new MontantAvecTaxes(2021, 0)
    }

    handleYearChange = (event) =>{
        // console.log("Year: " + e.target.value)
        console.log("key: " + event.target.id)
        const mnt = new MontantAvecTaxes(event.target.value, this.state.montantAvecTaxe.getMontantSansTaxe());
        this.setState({
            montantAvecTaxe : mnt
        })
    }

    handleAmountChange = (event) =>{
        console.log(event.target.value)
        const mnt = new MontantAvecTaxes(this.state.montantAvecTaxe.getYear(), event.target.value);
        this.setState({
            montantAvecTaxe : mnt
        })
    }

    outputDollars = (montant) => {
        return Math.round(montant*100)/100 + " $"
    }

    render() {
        const taxeTPS = this.outputDollars(this.state.montantAvecTaxe.getTPS());
        const taxeTVQ = this.outputDollars(this.state.montantAvecTaxe.getTVQ());
        const taxeAvecTaxe = this.outputDollars(this.state.montantAvecTaxe.getMontantAvecTaxe());
        const years = ["2021", "2020", "2019", "2018", "2017", "2016", "2015", "2014", "2013", "2012", "2011"];
        return (
            <div className="App"> 
                <fieldset>
                <form>
                    <legend>Choisissez l'année du calcul:</legend>
                    <select onChange={this.handleYearChange}>
                        {
                            years.map((year, index) => {
                                return <option key={index} id={index}>{year}</option>
                            })
                        }
                    </select>
                    
                    <p>
                        <legend>Entrez le montant avant taxe :</legend>
                        <input onChange={this.handleAmountChange} />
                    </p>
                    
                    {/*https://scriptverse.academy/tutorials/reactjs-defaultvalue-value.html*/}
                    <legend>TPS :</legend>
                    <input type="text" name="tps" value={taxeTPS} readOnly/>
                    <legend>TVQ :</legend>
                    <input type="text" name="tvq" value={taxeTVQ} readOnly/>
                    <legend>Montant Total :</legend>
                    <input type="text" name="montantAvecTaxe" value={taxeAvecTaxe} readOnly/>
                    </form>
                </fieldset>
            </div>
        );
    }
}

export default TaxeQC;